    ["Cocoa Bunny"] = {
        ["Your title reminds me of what Granny Jesse used to call us whenever we visited..."] = "Tu título me recuerda cómo solía llamarnos la abuela Jesse cada vez que visitábamos...",
        ["You've unlocked the 'Springtime' colour for the 'the Egg' title!"] = "¡Has desbloqueado el color 'Primavera' para el título 'el Huevo'!",
        ["She was always surrounded by the prettiest of flowers... Maybe they'll suit you too?"] = "Ella siempre estuvo rodeada de las flores más bonitas... ¿Quizás a ti también te quedarán bien?",
    },
    ["Coeden"] = {
        ["Hello...human. Welcome...to my store"] = "Hola...humano. Bienvenido... a mi tienda",
        ["Select an Option"] = "Selecciona una opción",
        ["Tell me about yourself."] = "Háblame de ti.",
        ["Oh...not much to tell."] = "Oh... no hay mucho que contar.",
        ["I...am Coeden. I...sell seeds."] = "Yo... soy Coeden. Yo... vendo semillas.",
        ["**Coeden: **Crwys...are my friends."] = "**Coeden: **Crwys... son mis amigos.",
        ["Take a look...at my seeds...for sale. I also sell...saplings."] = "Echa un vistazo... a mis semillas... a la venta. También vendo... retoños.",
        ["Show me your store."] = "Muéstrame tu tienda.",
        ["Why do you sell your offspring to random strangers?"] = "¿Por qué vendes a tu descendencia a extraños al azar?",
        ["They go...willingly."] = "Van... de buena gana.",
        ["But that's like chopping off a limb and giving it to me! You can't possibly have a use for the gold."] = "¡Pero eso es como cortarme un miembro y dármelo! No es posible que puedas utilizar el oro.",
        ["**Coeden: ** Gold...is shiny,...but I willingly...give of myself...for a helper...such as...you."] = "**Coeden: ** El oro... es brillante,... pero yo voluntariamente... me entrego... por una ayuda... como... tú.",
        ["Wow, thanks!"] = "¡Vaya, gracias!",
        ["I think I have earned some logs."] = "Creo que me he ganado algo de logs.",
        ["Such...impudence...from one who was...so helpful."] = "Qué... descaro... de alguien que fue... tan útil.",
        ["Sorry, may I please have my logs?"] = "Lo siento, ¿puedo tener mi logs?",
        ["Thank you!"] = "¡Gracias!",
        ["Skip the chat - bring on the flames."] = "Salta el chat: enciende las llamas.",
        ["This is for selling your offspring to strangers!"] = "¡Esto es por vender a tus hijos a extraños!",
        ["That...stings. Here...I give of myself...in penance."] = "Eso... duele. Aquí... me entrego... en penitencia.",
        ["You...already had your logs...return in...[tomorrow/[number] days.]"] = "Tú... ya recibiste tu logs...de regreso en...[tomorrow/[number] días.]",
        ["Hey, that tickles!"] = "¡Oye, eso hace cosquillas!",
        ["colour=#8A0808"] = "color=#8A0808",
    },
    ["Coenus"] = {
        ["Move along. There's no passage this way."] = "Sigue adelante. No hay paso por aquí.",
        ["Another worker who wants to go home so they can shirk off their duties? It's a one way trip; can't have you spreading plague."] = "¿Otro trabajador que quiere irse a casa para poder eludir sus obligaciones? Es un viaje de ida; No puedo dejar que propagues la plaga.",
        ["Go to Sophanem?"] = "¿Ir a Sophanem?",
        ["Yes."] = "Sí.",
        ["Pharaoh Osman has allowed passage between the two cities for friends of Menaphos. Would you like to leave?"] = "El faraón Osman ha permitido el paso entre las dos ciudades a los amigos de Menaphos. ¿Quieres irte?",
    },
    ["Col. O'Niall"] = {
        ["Hello there."] = "Hola.",
        ["Hello. What can I do for you?"] = "Hola. ¿Qué puedo hacer por ti?",
        ["Oh, I'm just wondering what you're doing."] = "Oh, sólo me pregunto qué estás haciendo.",
        ["A spot of fishing."] = "Un lugar para pescar.",
        ["That doesn't look much like a fishing rod."] = "Eso no se parece mucho a una caña de pescar.",
        ["That my friend, depends on what you're fishing for."] = "Eso, amigo mío, depende de lo que estés pescando.",
        ["And what would that be?"] = "¿Y cuál sería?",
        ["A little of this, a little of that; the usual things."] = "Un poco de esto, un poco de aquello; las cosas habituales.",
        ["Have you caught much?"] = "¿Has pescado mucho?",
        ["The odd bite here and there. Hmm."] = "Algún mordisco aquí y allá. Mmm.",
        ["What?"] = "¿Qué?",
        ["You look like a capable lad. Tell you what, when you've got a bit more experience under your belt, get yourself over to Falador."] = "Pareces un muchacho capaz. Te diré una cosa, cuando tengas un poco más de experiencia en tu haber, pásate a Falador.",
        ["What's in Falador?"] = "¿Qué hay en Falador?",
        ["An old friend of mine. You'll find him sitting on a bench in Falador Park. See what he can do for you."] = "Un viejo amigo mío. Lo encontrarás sentado en un banco del parque Falador. Vea lo que él puede hacer por usted.",
        ["What's his name? Who should I say sent me?"] = "¿Cómo se llama? ¿Quién debería decir que me envió?",
        ["None of that matters if you can find him and if you're ready my name isn't necessary."] = "Nada de eso importa si puedes encontrarlo y si estás listo, mi nombre no es necesario.",
        ["Oh right. I'll get going then. Goodbye."] = "Ah, claro. Entonces me iré. Adiós.",
        ["Goodbye and good luck."] = "Adiós y buena suerte.",
        ["Ah hello, Player. Good to see you."] = "Ah, hola, Player. Es bueno verte.",
        ["Um, how do you know my name?"] = "Mmm, ¿cómo sabes mi nombre?",
        ["By reputation. I heard about what you did with Solus Dellagar; good job."] = "Por reputación. Me enteré de lo que hiciste con Solus Dellagar; buen trabajo.",
        ["But but but, that was classified! How can you possibly know that?"] = "Pero, pero, ¡eso fue clasificado! ¿Cómo es posible que sepas eso?",
        ["I have my contacts."] = "Tengo mis contactos.",
        ["You're one of the Black Knights, aren't you?"] = "Eres uno de los Black Knights, ¿no?",
        ["Don't be silly, boy."] = "No seas tonto, muchacho.",
        ["If I was a Black Knight, do you really think I'd be just sitting here?"] = "Si yo fuera un Black Knight, ¿realmente crees que estaría sentado aquí?",
        ["Well, I don't know."] = "Bueno, no lo sé.",
        ["I'd be looting your gear before you landed in Lumbridge my boy."] = "Estaría saqueando tu equipo antes de que aterrizaras en Lumbridge, muchacho.",
        ["Hmm. Who are you, really?"] = "Mmm. ¿Quién eres realmente?",
        ["Oh, I'm sure you'll find out eventually."] = "Oh, estoy seguro de que eventualmente lo descubrirás.",
        ["Let's just say that for the moment that information is beyond your means."] = "Digamos que por el momento esa información está fuera de tu alcance.",
        ["You're very cryptic, aren't you?"] = "Eres muy críptico, ¿no?",
        ["I need to be, it's how I've stayed alive this long."] = "Necesito estarlo, así es como me he mantenido vivo durante tanto tiempo.",
        ["But..."] = "Pero...",
        ["That's enough for now. I'm sure we'll speak again sometime soon."] = "Es suficiente por ahora. Estoy seguro de que volveremos a hablar pronto.",
        ["Goodbye, Player."] = "Adiós, Player.",
        ["Sigh, see you soon."] = "Suspiro, hasta pronto.",
    },
    ["Colin"] = {
        ["He looks so happy to be here."] = "Se ve muy feliz de estar aquí.",
    },
    ["Colonel Grenda"] = {
        ["Come on, you sons of trolls! D'you want to live forever?"] = "¡Vamos, hijos de trolls! ¿Quieres vivir para siempre?",
        ["**Select an option**"] = "**Seleccione una opción**",
        ["What's happening here?"] = "¿Qué está pasando aquí?",
        ["We're holding the line, human! The chaos dwarves won't get into our mines again!"] = "¡Estamos manteniendo la línea, humano! ¡Los enanos del caos no volverán a entrar en nuestras minas!",
        ["Tell me about the hand cannoneers."] = "Háblame de los cañoneros manuales.",
        ["They've got some new Red Axe weapon! They're like miniature cannons. You might get your hands on one if you join the fight."] = "¡Tienen una nueva arma Red Axe! Son como cañones en miniatura. Es posible que consigas uno si te unes a la lucha.",
        ["I don't trust them. You've got to use Firemaking to keep them stable, and you can never be sure they won't explode in your face. That's not how a Black Guard soldier ought to go."] = "No confío en ellos. Tienes que usar Firemaking para mantenerlos estables y nunca puedes estar seguro de que no te explotarán en la cara. Así no es como debería actuar un soldado de Black Guard.",
        ["Tell me about the chaos dwogres."] = "Háblame de los dwogres del caos.",
        ["Another product of the Red Axe's experiments!"] = "¡Otro producto de los experimentos de Red Axe!",
        ["Dwarves can't use magic, but ogres can. Looks like the Red Axe have added some ogre to the mix to let them cast spells!"] = "Los enanos no pueden usar magia, pero los ogros sí. ¡Parece que Red Axe ha agregado algo de ogro a la mezcla para permitirles lanzar hechizos!",
        ["They're tough, but they go down eventually."] = "Son difíciles, pero eventualmente bajan.",
        ["Goodbye."] = "Adiós.",
        ["You're a little tall, soldier, but we could use a man like you! Get down there and kick some chaos dwarf ass! For Keldagrim!"] = "Eres un poco alto, soldado, ¡pero nos vendría bien un hombre como tú! ¡Baja y patea el trasero de un enano del caos! ¡Por Keldagrim!",
        ["We defeated the Red Axe - why are they still attacking?"] = "Derrotamos al Hacha Roja. ¿Por qué siguen atacando?",
        ["The Red Axe unleashed forces they couldn't control, human! This is what happens when you try to play Guthix! These chaos dwarves and dwogres have become a self-sustaining population. They're going to keep coming - all we can do is hold the line."] = "¡El Hacha Roja desató fuerzas que no podían controlar, humano! ¡Esto es lo que sucede cuando intentas jugar a Guthix! Estos enanos y dwogres del caos se han convertido en una población autosuficiente. Van a seguir llegando; lo único que podemos hacer es mantener la línea.",
        ["I'm thinking of it as a training ground for Black Guards. Once you've been face to face with a screaming chaos dwarf waving a tube full of gunpowder, then you can call yourself a dwarven warrior."] = "Lo considero un campo de entrenamiento para los Guardias Negros. Una vez que te hayas encontrado cara a cara con un enano del caos que grita agitando un tubo lleno de pólvora, podrás llamarte guerrero enano.",
        ["Tell me about your assault on the Red Axe base."] = "Cuéntame sobre tu asalto a la base de Red Axe.",
        ["It was thanks to you, human! If you hadn't destroyed the cannons and raised the bridges, we'd never have gotten the army across."] = "¡Fue gracias a ti, humano! Si no hubieras destruido los cañones y levantado los puentes, nunca habríamos logrado que el ejército cruzara.",
        ["After that, the rest of the Red Axe didn't pose much of a challenge. Trolls aren't the brightest bunch, but I'll say this for them - if you point them at a locked door, that door won't last long."] = "Después de eso, el resto del Red Axe no representó un gran desafío. Los trolls no son el grupo más inteligente, pero diré esto por ellos: si les apuntas hacia una puerta cerrada, esa puerta no durará mucho.",
        ["It's just a shame we got there too late and missed your fun with Hreidmar and Grimsson. I'd have liked to give them a taste of my axe!"] = "Es una pena que hayamos llegado demasiado tarde y nos hayamos perdido tu diversión con Hreidmar y Grimsson. ¡Me hubiera gustado darles una probada de mi hacha!",
    },
    ["Colonel Radick"] = {
        ["Who goes there? Friend or foe?"] = "¿Quién va allí? ¿Amigo o enemigo?",
        ["Select an Option"] = "Selecciona una opción",
        ["Friend."] = "Amigo.",
        ["Ok good to hear it."] = "Ok, es bueno escucharlo.",
        ["Foe!"] = "¡Enemigo!",
        ["Oh righty..."] = "Ah, claro...",
        ["Why is this town so heavily defended?"] = "¿Por qué esta ciudad está tan fuertemente defendida?",
        ["Yanille is on the southwest border of Kandarin, Beyond here you go into the Feldip hills which is major Ogre territory. Our job is to defend Yanille from the ogres."] = "Yanille está en la frontera suroeste de Kandarin. Más allá de aquí, se adentra en las colinas Feldip, que es el principal territorio de los ogros. Nuestro trabajo es defender Yanille de los ogros.",
    },
    ["Colonised Lumbridge guard"] = {
        ["You attempt to catch some algae..."] = "Intentas atrapar algunas algas...",
        ["You catch some fungal algae."] = "Coges algunas algas fúngicas.",
        ["Category:Non-spoken transcripts"] = "Categoría: Transcripciones no habladas",
    },
    ["Colonised Varrock guard"] = {
        ["You attempt to catch some algae..."] = "Intentas atrapar algunas algas...",
        ["You catch some fungal algae."] = "Coges algunas algas fúngicas.",
        ["Category:Non-spoken transcripts"] = "Categoría: Transcripciones no habladas",
    },
    ["Commander Akhomet (Imperial)"] = {
        ["Choose an option:"] = "Elige una opción:",
        ["How did you become the leader of the Menaphite Guard?"] = "¿Cómo te convertiste en el líder de Menaphite Guard?",
        ["My father was a blacksmith and my mother was a general in the Pharaoh's army. I admired my mother greatly, although she was by no means an easy woman to love. She lived in a time where uprisings were common and public opinion was almost impossible to quell. It seemed almost reflexive for me to follow in her footsteps, and she made sure I was never even slightly pandered to."] = "Mi padre era herrero y mi madre era general en el ejército del faraón. Admiraba mucho a mi madre, aunque no era en modo alguno una mujer fácil de amar. Vivió en una época en la que los levantamientos eran comunes y la opinión pública era casi imposible de sofocar. Me pareció casi un acto reflejo seguir sus pasos, y ella se aseguró de que nunca me complaceran ni un poco.",
        ["I think if left down to my mother, I would be as harsh and commanding as her, but my father taught me compassion and empathy. Soft skills are essential in this line of work, and I believe they are what gave me the edge."] = "Creo que si dependiera de mi madre, sería tan duro y autoritario como ella, pero mi padre me enseñó la compasión y la empatía. Las habilidades interpersonales son esenciales en esta línea de trabajo y creo que fueron las que me dieron la ventaja.",
        ["I will always get the job done, but never at the expense of my peers."] = "Siempre haré el trabajo, pero nunca a expensas de mis compañeros.",
        ["What do you do around here?"] = "¿Qué haces por aquí?",
        ["Me and my men keep the peace. There is so much that the citizens have to be annoyed about, but that annoyance festers into anger, and anger is misplaced easily. We make sure that public opinion is kept in line in any way we can, lest they find themselves misplaced."] = "Mis hombres y yo mantenemos la paz. Hay tantas cosas por las que los ciudadanos deben estar molestos, pero esa molestia se convierte en ira, y la ira se extravía fácilmente. Nos aseguramos de que la opinión pública se mantenga a raya en todo lo que podamos, para que no se encuentre fuera de lugar.",
        ["Whether that be through taking the law into our own hands or ensuring the safety of our monarch, it's the very least we can do for the men and women of Menaphos."] = "Ya sea tomando la justicia por nuestra mano o garantizando la seguridad de nuestro monarca, es lo mínimo que podemos hacer por los hombres y mujeres de Menaphos.",
        ["I have something I'd like to hand in!"] = "¡Tengo algo que me gustaría entregar!",
        ["Greetings and salutations, soldier! You say you've found something I might be interested in?"] = "¡Saludos y saludos, soldado! ¿Dices que has encontrado algo que podría interesarme?",
        ["Very good. We have been rounding up false idols such as those for incineration, by order of the Pharaoh."] = "Muy bien. Hemos estado reuniendo ídolos falsos, como aquellos para incinerarlos, por orden del Faraón.",
    },
    ["Commander Akhomet"] = {
        ["Choose an option:"] = "Elige una opción:",
        ["How did you become the leader of the Menaphite Guard?"] = "¿Cómo te convertiste en el líder de Menaphite Guard?",
        ["My father was a blacksmith and my mother was a general in the Pharaoh's army. I admired my mother greatly, although she was by no means an easy woman to love. She lived in a time where uprisings were common and public opinion was almost impossible to quell. It seemed almost reflexive for me to follow in her footsteps, and she made sure I was never even slightly pandered to."] = "Mi padre era herrero y mi madre era general en el ejército del faraón. Admiraba mucho a mi madre, aunque no era en modo alguno una mujer fácil de amar. Vivió en una época en la que los levantamientos eran comunes y la opinión pública era casi imposible de sofocar. Me pareció casi un acto reflejo seguir sus pasos, y ella se aseguró de que nunca me complaceran ni un poco.",
        ["I think if left down to my mother, I would be as harsh and commanding as her, but my father taught me compassion and empathy. Soft skills are essential in this line of work, and I believe they are what gave me the edge."] = "Creo que si dependiera de mi madre, sería tan duro y autoritario como ella, pero mi padre me enseñó la compasión y la empatía. Las habilidades interpersonales son esenciales en esta línea de trabajo y creo que fueron las que me dieron la ventaja.",
        ["I will always get the job done, but never at the expense of my peers."] = "Siempre haré el trabajo, pero nunca a expensas de mis compañeros.",
        ["What do you do around here?"] = "¿Qué haces por aquí?",
        ["Me and my men keep the peace. There is so much that the citizens have to be annoyed about, but that annoyance festers into anger, and anger is misplaced easily. We make sure that public opinion is kept in line in any way we can, lest they find themselves misplaced."] = "Mis hombres y yo mantenemos la paz. Hay tantas cosas por las que los ciudadanos deben estar molestos, pero esa molestia se convierte en ira, y la ira se extravía fácilmente. Nos aseguramos de que la opinión pública se mantenga a raya en todo lo que podamos, para que no se encuentre fuera de lugar.",
        ["Whether that be through taking the law into our own hands or ensuring the safety of our monarch, it's the very least we can do for the men and women of Menaphos."] = "Ya sea tomando la justicia por nuestra mano o garantizando la seguridad de nuestro monarca, es lo mínimo que podemos hacer por los hombres y mujeres de Menaphos.",
        ["I have something I'd like to hand in!"] = "¡Tengo algo que me gustaría entregar!",
        ["Greetings and salutations, soldier! You say you've found something I might be interested in?"] = "¡Saludos y saludos, soldado! ¿Dices que has encontrado algo que podría interesarme?",
        ["Very good. We have been rounding up false idols such as those for incineration, by order of the Pharaoh."] = "Muy bien. Hemos estado reuniendo ídolos falsos, como aquellos para incinerarlos, por orden del Faraón.",
    },
    ["Commander Connad"] = {
        ["Hello?"] = "¿Hola?",
        ["Sorry soldier, you don't have permission to speak with me yet. Go and talk to the Captain."] = "Lo siento soldado, todavía no tienes permiso para hablar conmigo. Ve y habla con el Capitán.",
        ["You can't claim any rewards until you have completed the tutorial. Go and see Captain Cain."] = "No puedes reclamar ninguna recompensa hasta que hayas completado el tutorial. Ve a ver Captain Cain.",
        ["I believe you might be able to reward me for my progress in this arena?"] = "Creo que podrías recompensarme por mi progreso en este campo.",
        ["Well, that depends upon your skill levels for each role. What's your name, soldier?"] = "Bueno, eso depende de tu skill levels para cada rol. ¿Cómo te llamas, soldado?",
        ["Player, Sir!"] = "¡Player, señor!",
        ["Okay. What exactly do you want to know, Player?"] = "Está bien. ¿Qué es exactamente lo que quieres saber, Player?",
        ["Can I trade some of my points?"] = "¿Puedo canjear algunos de mis puntos?",
        ["Of course."] = "Por supuesto.",
        ["What points do I have so far, sir?"] = "¿Qué puntos tengo hasta ahora, señor?",
        ["Let me check... You have: *x* Attacker Honour Points, *x* Defender Honour Points, *x* Collector Honour Points, and *x* Healer Honour Points."] = "Déjame comprobar... Tienes: *x* puntos de honor de atacante, *x* puntos de honor de defensor, *x* puntos de honor de coleccionista y *x* puntos de honor de sanador.",
        ["Could I have a 'Queen Help' book?"] = "¿Podría darme un libro de 'Queen Help'?",
        ["Could I have a Queen Help book?"] = "¿Podría darme un libro de Queen Help?",
        ["By all means."] = "Por supuesto.",
        ["Could I change my current wave?"] = "¿Puedo cambiar mi ola actual?",
        ["I can change it down to wave 1 and you're currently on wave *x*. I'll give you a ticket for use on the wave *x* door, so you can change your wave back to that room."] = "Puedo cambiarlo a la onda 1 y actualmente estás en la onda *x*. Te daré un boleto para usar en la puerta wave *x*, para que puedas cambiar tu wave de regreso a esa habitación.",
        ["Yes, reset my wave to one."] = "Sí, restablece mi ola a uno.",
        ["Very well."] = "Muy bien.",
        ["No, I want to stay on wave *x*."] = "No, quiero permanecer en la ola *x*.",
        ["That is all, sir."] = "Eso es todo, señor.",
        ["Very well, on your way."] = "Muy bien, en camino.",
    },
    ["Commander Denulth"] = {
        ["Hello!"] = "¡Hola!",
        ["Welcome back friend!"] = "¡Bienvenido de nuevo amigo!",
        ["Select an Option"] = "Selecciona una opción",
        ["How goes your fight with the trolls?"] = "¿Cómo va tu pelea con los trolls?",
        ["We have pinned them down thanks to the vantage point on the cliffs that you found."] = "Los hemos inmovilizado gracias al mirador sobre los acantilados que encontraste.",
        ["They can't reach us with rocks, nor climb up to attack. We can rain arrows down on them with impunity!"] = "No pueden alcanzarnos con piedras ni trepar para atacar. ¡Podemos lloverles flechas con impunidad!",
        ["Friend, we are indebted to you!"] = "Amigo, ¡estamos en deuda contigo!",
        ["Good luck!"] = "¡Buena suerte!",
        ["We are busy preparing for an attack by night. Godric knows of a secret entrance to the stronghold."] = "Estamos ocupados preparándonos para un ataque nocturno. Godric sabe de una entrada secreta a la fortaleza.",
        ["Once we destroy the stronghold Burthorpe will be safe!"] = "Una vez que destruyamos la fortaleza, ¡Burthorpe estará a salvo!",
        ["cond=Having not yet delivered supplies to the Ambush Commander five times:"] = "cond=No haber entregado aún suministros al Ambush Commander cinco veces:",
        ["Well, I suppose that the archers on the overlook could do with some more supplies."] = "Bueno, supongo que a los arqueros del mirador les vendría bien más suministros.",
        ["You place the heavy crate of supplies in your pack."] = "Colocas la pesada caja de suministros en tu mochila.",
        ["Here, take these supplies up to the Ambush Commander at the ambush point."] = "Aquí, lleva estos suministros al Ambush Commander en el punto de emboscada.",
        ["It has some supplies for the men, such as more arrows and replacement bows, as well as some things they can put together to make the ambush point better equipped."] = "Tiene algunos suministros para los hombres, como más flechas y arcos de repuesto, así como algunas cosas que pueden juntar para equipar mejor el punto de emboscada.",
        ["Plus a few luxuries like cakes, and letters from friends and family. That sort of thing."] = "Además de algunos lujos como pasteles y cartas de amigos y familiares. Ese tipo de cosas.",
        ["The Ambush Commander has some reward lamps. Once they get this gear he will give you some to help with your training."] = "El Ambush Commander tiene algunas lámparas de recompensa. Una vez que obtengan este equipo, él te dará algunos para ayudarte con tu entrenamiento.",
        ["All right, I will drop this off immediately."] = "Muy bien, dejaré esto inmediatamente.",
        ["Well, if you wouldn't mind delivering those supplies for me, I may have some more to send you off with."] = "Bueno, si no te importa entregarme esos suministros, puede que tenga algunos más para despedirte.",
        ["The Ambush Commander at the ambush point over Death Plateau has a supply of reward lamps that he will give you when he gets that gear."] = "El Ambush Commander en el punto de emboscada sobre Death Plateau tiene un suministro de lámparas de recompensa que te dará cuando consiga ese equipo.",
        ["I thought the White Knights controlled Asgarnia?"] = "¿Pensé que los Caballeros Blancos controlaban Asgarnia?",
        ["You are right, citizen. The White Knights have taken advantage of the old and weak king. They control most of Asgarnia, including Falador, but they do not control Burthorpe!"] = "Tienes razón, ciudadano. Los Caballeros Blancos se han aprovechado del viejo y débil rey. Controlan la mayor parte de Asgarnia, incluido Falador, ¡pero no controlan Burthorpe!",
        ["We are the prince's elite troops! We keep Burthorpe secure!"] = "¡Somos las tropas de élite del príncipe! ¡Mantenemos Burthorpe seguro!",
        ["The White Knights have overlooked us, until now! They are pouring money into their war against the Black Knights, so they are looking for an excuse to stop our funding and I'm afraid they may have found it!"] = "¡Los Caballeros Blancos nos han pasado por alto hasta ahora! Están invirtiendo dinero en su guerra contra el Black Knights, por lo que están buscando una excusa para detener nuestra financiación y ¡me temo que la han encontrado!",
        ["If we can not destroy the troll camp on Death Plateau then the Imperial Guard will be disbanded and Burthorpe will come under control of the White Knights. We cannot let this happen!"] = "Si no podemos destruir el campamento troll en Death Plateau, entonces la Guardia Imperial se disolverá y Burthorpe quedará bajo el control de los Caballeros Blancos. ¡No podemos permitir que esto suceda!",
        ["See you about, Denulth!"] = "¡Nos vemos, Denulth!",
        ["Saradomin be with you, friend!"] = "¡Saradomin estará contigo, amigo!",
    },
    ["Commander Loman"] = {
        ["Sir - erm, permission to speak?"] = "Señor - erm, ¿permiso para hablar?",
        ["Yes."] = "Sí.",
        ["**1. What rank are you?**"] = "**1. ¿Qué rango tienes?**",
        ["What rank are you?"] = "¿Qué rango tienes?",
        ["I am a commander. As you ask, I have been here nine years and am third-in-command of A.R.M.S."] = "Soy un comandante. Como preguntas, llevo aquí nueve años y soy el tercero al mando de A.R.M.S.",
        ["Now, you didn't salute, did you?"] = "Ahora, no saludaste, ¿verdad?",
        ["Oh, sorry sir."] = "Oh, lo siento señor.",
        ["*(The player performs the \"Salute\" emote)*"] = "*(el player realiza el gesto \"Saludo\")*",
        ["Better now than never, but try not to forget - especially if you speak to higher officers."] = "Mejor ahora que nunca, pero trata de no olvidarlo, especialmente si hablas con oficiales superiores.",
        ["What are they like?"] = "¿Cómo son?",
        ["Remember your place, young commander. You should not be asking such questions."] = "Recuerda tu lugar, joven comandante. No deberías hacer esas preguntas.",
        ["Sorry, sir."] = "Lo siento, señor.",
        ["**2. Can I exchange my reward credits?**"] = "**2. ¿Puedo canjear mis créditos de recompensa?**",
        ["Can I exchange my reward credits?"] = "¿Puedo canjear mis créditos de recompensa?",
        ["Well, you must be getting proficient to have reached my office. What are you looking for?"] = "Bueno, debes ser competente para haber llegado a mi oficina. ¿Qué estás buscando?",
        ["**2.1. Reward items.**"] = "**2.1. Artículos de recompensa.**",
        ["*(Opens Commander Loman's reward shop)*"] = "*(Abre la tienda de recompensas de Commander Loman)*",
        ["**2.2. Spoils of war.**"] = "**2.2. Botín de guerra.**",
        ["*(Opens Spoils of War interface)*"] = "*(Abre Botín de la interfaz War)*",
        ["**2.3. Imbued rings.**"] = "**2.3. Anillos imbuidos.**",
        ["I can imbue a few rings to give you additional combat boosts. Which would you like?"] = "Puedo imbuir algunos anillos para darte mejoras de combate adicionales. ¿Cuál te gustaría?",
        ["**2.3.1. Sapphire ring (74,600 reward credits)**"] = "**2.3.1. Anillo de zafiro (74,600 créditos de recompensa)**",
        ["*(The following dialogue takes place if you don't own a sapphire ring)*"] = "*(El siguiente diálogo tiene lugar si no posees un anillo de zafiro)*",
        ["Sapphire ring, please."] = "Anillo de zafiro, por favor.",
        ["Actually, I don't have any of those rings with me."] = "En realidad, no tengo ninguno de esos anillos conmigo.",
        ["**2.3.2. Emerald ring (74,600 reward credits)**"] = "**2.3.2. Anillo de esmeralda (74,600 créditos de recompensa)**",
        ["*(The following dialogue takes place if you don't own a emerald ring)*"] = "*(El siguiente diálogo tiene lugar si no posees un anillo de esmeralda)*",
        ["Emerald ring, please."] = "Anillo de esmeralda, por favor.",
        ["**2.3.3. Ruby ring (89,600 reward credits)**"] = "**2.3.3. Anillo de rubí (89 600 créditos de recompensa)**",
        ["*(The following dialogue takes place if you don't own a ruby ring)*"] = "*(El siguiente diálogo tiene lugar si no posees un anillo de rubí)*",
        ["Ruby ring, please."] = "Anillo de rubí, por favor.",
        ["**2.3.4. Diamond ring (89,600 reward credits)**"] = "**2.3.4. Anillo de diamantes (89 600 créditos de recompensa)**",
        ["*(The following dialogue takes place if you don't own a diamond ring)*"] = "*(El siguiente diálogo tiene lugar si no posees un anillo de diamantes)*",
        ["Diamond ring, please."] = "Anillo de diamantes, por favor.",
        ["**2.3.5. No, thanks**"] = "**2.3.5. No, gracias**",
        ["No, thanks."] = "No, gracias.",
        ["**2.4. I've changed my mind, sir.**"] = "**2.4. He cambiado de opinión, señor.**",
        ["I've changed my mind, sir."] = "He cambiado de opinión, señor.",
        ["Then be on your way."] = "Entonces sigue tu camino.",
        ["**3. Can I change my rank prefix please?**"] = "**3. ¿Puedo cambiar mi prefijo de rango, por favor?**",
        ["Can I change my rank prefix please?"] = "¿Puedo cambiar mi prefijo de rango, por favor?",
        ["Of course. What rank prefix would you like?"] = "Por supuesto. ¿Qué prefijo de rango te gustaría?",
        ["**3.1. No prefix.**"] = "**3.1. Sin prefijo.**",
        ["No prefix."] = "Sin prefijo.",
        ["As you wish."] = "Como desees.",
        ["**3.2. Junior Cadet.**"] = "**3.2. Cadete Junior.**",
        ["Junior Cadet."] = "Cadete Junior.",
        ["**3.3. Serjeant.**"] = "**3.3. Sargento.**",
        ["Serjeant."] = "Sargento.",
        ["**3.4. Commander.**"] = "**3.4. Comandante.**",
        ["Commander."] = "Comandante.",
        ["**3.5. War-chief.**"] = "**3.5. War-jefe.**",
        ["War-chief"] = "War-jefe",
        ["**4. May I leave, sir?**"] = "**4. ¿Puedo irme, señor?**",
        ["May I leave, sir?"] = "¿Puedo irme, señor?",
        ["By all means."] = "Por supuesto.",
    },
    ["Commander Montai"] = {
        ["Hello."] = "Hola.",
        ["I can't talk now. Can't you see we're trying to win a battle here? If we can't hold back Khazard's men we're all doomed."] = "No puedo hablar ahora. ¿No ves que estamos tratando de ganar una batalla aquí? Si no podemos contener a los hombres de Khazard, estamos todos condenados.",
        ["Hello Montai, how are you?"] = "Hola Montai, ¿cómo estás?",
        ["I'm ok, this battle is going to take longer to win than I expected. The Khazard troops won't give up even without the orb."] = "Estoy bien, ganar esta batalla va a tomar más tiempo de lo que esperaba. Las tropas de Khazard no se rendirán ni siquiera sin el orbe.",
        ["Hang in there."] = "Aguanta.",
    },
    ["Commander Yodri"] = {
        ["Hello there. Have you seen some goblins around here?"] = "Hola. ¿Has visto algunos duendes por aquí?",
        ["Why? Who are you?"] = "¿Por qué? ¿Quién eres?",
        ["Yodri, Commander with the Black Guard."] = "Yodri, comandante del Black Guard.",
        ["My men and I are chasing some goblin raiders. Apparently they have been seen in this area."] = "Mis hombres y yo estamos persiguiendo a unos asaltantes goblin. Al parecer han sido vistos en esta zona.",
        ["Select an option"] = "Selecciona una opción",
        ["I've killed some goblin raiders. Can I have a reward?"] = "He matado a algunos asaltantes goblin. ¿Puedo tener una recompensa?",
        ["Yodri cannot give you all your reward items. You need to have 2 free spaces in your inventory to be able to hold everything."] = "Yodri no puede darte todos tus artículos de recompensa. Necesitas tener 2 espacios libres en tu inventario para poder guardar todo.",
        ["Is there anything else I can help you with?"] = "¿Hay algo más en lo que pueda ayudarte?",
        ["I think that's everything. Thanks for all the hard work! Can I help you with anything else?"] = "Creo que eso es todo. ¡Gracias por todo el arduo trabajo! ¿Puedo ayudarte con algo más?",
        ["Who are these raiders?"] = "¿Quiénes son estos asaltantes?",
        ["We've had reports that goblins from the village near Taverley have been launching raids."] = "Hemos recibido informes de que los duendes de la aldea cercana a Taverley han estado lanzando incursiones.",
        ["They haven't hit anywhere too populated yet. Just farms, some copper and iron mines, that kind of thing."] = "Todavía no han llegado a ningún lugar demasiado poblado. Sólo granjas, algunas minas de cobre y hierro, ese tipo de cosas.",
        ["The problem is they are damaging trade with humans, and the Consortium doesn't like that."] = "El problema es que están perjudicando el comercio con humanos, y al Consorcio no le gusta eso.",
        ["So they dispatched me and my mean to deal with the issue."] = "Así que nos enviaron a mí y a mi medio para solucionar el problema.",
        ["Just three of you?"] = "¿Solo ustedes tres?",
        ["Three is more than enough for this rabble! The problem is they run before we can get stuck in."] = "¡Tres son más que suficientes para esta chusma! El problema es que corren antes de que podamos quedarnos atrapados.",
        ["One day, we'll catch up with them. Then, we can take them down."] = "Un día los alcanzaremos. Entonces podremos acabar con ellos.",
        ["Of course, if you can help out, we'd appreciate it."] = "Por supuesto, si puedes ayudar, te lo agradeceríamos.",
        ["Is there some sort of reward?"] = "¿Hay algún tipo de recompensa?",
        ["A reward? Well there is a standing bounty of goblin raiders, so I suppose I could pay you something."] = "¿Una recompensa? Bueno, hay una recompensa constante por los asaltantes goblins, así que supongo que podría pagarte algo.",
        ["How about this? For every goblin you kill, I'll give you some basic items from the Black Guard's stores."] = "¿Qué tal esto? Por cada duende que mates, te daré algunos artículos básicos de las tiendas de Black Guard.",
        ["If you kill a goblin who's stealing wood, I'll give you some logs. If they are after minerals I will give you some ores."] = "Si matas a un duende que está robando madera, te daré logs. Si buscan minerales, te daré algunos minerales.",
        ["If they are pillaging a farm, you can have whatever seeds I can scrape together."] = "Si están saqueando una granja, puedes quedarte con todas las semillas que pueda juntar.",
        ["I'll even let you keep everything he's got on him when he dies as well. You can't say fairer than that."] = "Incluso te dejaré conservar todo lo que tenga cuando muera. No se puede decir más justo que eso.",
        ["Thanks! It's a deal."] = "¡Gracias! Es un trato.",
        ["I've also heard that the leader is carrying some unique items. If you kill him, maybe you can steal from them as well."] = "También escuché que el líder lleva algunos artículos únicos. Si lo matas, tal vez puedas robarles también.",
        ["Good luck!"] = "¡Buena suerte!",
        ["Stay safe, human. These raiders could be anywhere."] = "Mantente a salvo, humano. Estos asaltantes podrían estar en cualquier lugar.",
        ["Hello again. Have you seen any of those goblin raiders?"] = "Hola de nuevo. ¿Has visto a alguno de esos asaltantes duendes?",
    },
    ["Commentator booth"] = {
        ["*(One of the following comments may randomly be heard:)*"] = "*(Es posible que se escuche uno de los siguientes comentarios al azar:)*",
        ["*(One of the following comments may randomly be heard during the race:)*"] = "*(Uno de los siguientes comentarios puede escucharse aleatoriamente durante la carrera:)*",
        ["thumb|To moo is bovine."] = "pulgar|Moo es bovino.",
        ["*(Continues with one of the following comments:)*"] = "*(Continúa con uno de los siguientes comentarios :)*",
        ["thumb|A troll. With a propeller cap. And a tutu."] = "pulgar|Un troll. Con tapa de hélice. Y un tutú.",
        ["Category:NPC dialogue"] = "Categoría: Diálogo NPC",
    },
    ["Commodore Matthias"] = {
        ["Welcome to the Void Knight Outpost. I'm Commodore Matthias and I'm in charge here. Can I help you with anything?"] = "Bienvenido al puesto avanzado Void Knight. Soy Commodore Matthias y estoy a cargo aquí. ¿Puedo ayudarte con algo?",
        ["Select an Option"] = "Selecciona una opción",
        ["Who are you?"] = "¿Quién eres?",
        ["I'm a Void Knight, one of the order of Guthix. We are warriors of balance who do Guthix's work in Gielinor."] = "Soy un Void Knight, uno de la orden de Guthix. Somos guerreros del equilibrio que hacemos el trabajo de Guthix en Gielinor.",
        ["Wow, can I join?"] = "Vaya, ¿puedo unirme?",
        ["Entry is strictly invite only, however we do need help continuing Guthix's work."] = "La entrada es estrictamente solo por invitación, sin embargo, necesitamos ayuda para continuar con el trabajo de Guthix.",
        ["What kind of work?"] = "¿Qué tipo de trabajo?",
        ["**Player:** What kind of work?"] = "**Player:** ¿Qué tipo de trabajo?",
        ["Ah well you see we try to keep Gielinor as Guthix intended, it's very challenging. Actually we've been having some problems recently, maybe you could help us?"] = "Ah, bueno, verás, intentamos mantener Gielinor como pretendía Guthix, es un gran desafío. De hecho, hemos tenido algunos problemas recientemente, ¿quizás podrías ayudarnos?",
        ["What's the problem?"] = "¿Cuál es el problema?",
        ["Well the order has become quite diminished over the years, it's a very long process to learn the skills of a Void Knight. Recently there have been breaches into our realm from somewhere else, and strange creatures have been pouring through. We can't let that happen, and we'd be very grateful if you'd help us."] = "Bueno, el orden ha disminuido bastante con el paso de los años, es un proceso muy largo aprender las habilidades de un Void Knight. Recientemente ha habido irrupciones en nuestro reino desde algún otro lugar, y han estado entrando extrañas criaturas. No podemos permitir que eso suceda y le agradeceríamos mucho que nos ayudara.",
        ["[Menu]: Select an Option"] = "[Menú]: seleccione una opción",
        ["How can I help?"] = "¿Cómo puedo ayudar?",
        ["We send launchers from our outpost to the nearby islands. If you go and wait in the lander there that'd really help."] = "Enviamos lanzadores desde nuestro puesto de avanzada a las islas cercanas. Si vas y esperas en el módulo de aterrizaje, eso sería de gran ayuda.",
        ["Sorry, but I can't."] = "Lo siento, pero no puedo.",
        ["What's 'Gielinor'?"] = "¿Qué es 'Gielinor'?",
        ["**Player:** What's 'Gielinor'?"] = "**Player:** ¿Qué es 'Gielinor'?",
        ["It is the name that Guthix gave to this world, so we honour him with its use."] = "Es el nombre que Guthix le dio a este mundo, por eso lo honramos con su uso.",
        ["I'd rather not, sorry."] = "Preferiría no hacerlo, lo siento.",
        ["Good luck with that."] = "Buena suerte con eso.",
        ["Uh huh, sure."] = "Ajá, claro.",
        ["What is this place?"] = "¿Qué es este lugar?",
        ["This is our outpost. From here we send launches out to the nearby islands to beat back the invaders."] = "Este es nuestro puesto de avanzada. Desde aquí enviamos lanchas a las islas cercanas para hacer retroceder a los invasores.",
        ["What invaders?"] = "¿Qué invasores?",
        ["Recently there have been breaches into our realm from somewhere else, and strange creatures have been pouring through. We can't let that happen, and we'd be very grateful if you'd help us."] = "Recientemente ha habido irrupciones en nuestro reino desde algún otro lugar y han estado entrando extrañas criaturas. No podemos permitir que eso suceda y le agradeceríamos mucho que nos ayudara.",
        ["I'm fine, thanks."] = "Estoy bien, gracias.",
    },
    ["Competition Judge"] = {
        ["*(If player has 1000 archery tickets in inventory)*"] = "*(Si el jugador tiene 1000 boletos de tiro con arco en el inventario)*",
        ["**Competition Judge**Wow, I see that you've got yourself a whole load of archery tickets. Well done!"] = "**Competition Judge** Vaya, veo que tienes un montón de entradas de tiro con arco. ¡Bien hecho!",
        ["**Competition Judge**Hello there. Would you like to take part in the archery competition? It only costs 200 coins to enter."] = "**Competition Judge**Hola. ¿Te gustaría participar en el concurso de tiro con arco? La entrada solo cuesta 200 coins.",
        ["What would you lik;"] = "¿Qué te gustaría?",
        ["Sure, I'll give it a go."] = "Claro, lo intentaré.",
        ["You pay the judge and he gives you 10 bronze arrows."] = "Le pagas al juez y él te da 10 flechas de bronce.",
        ["What are the rules?"] = "¿Cuáles son las reglas?",
        ["**Competition Judge** The rules are very simple: You're given 10 shots at the targets. For each hit you will receive points. At the end I'll give you 1 ticket for every 10 points. The tickets can be exchanged for goods from our stores. So... would you like to try it? The fee is only 200 coins."] = "**Competition Judge** Las reglas son muy simples: tienes 10 disparos a los objetivos. Por cada acierto recibirás puntos. Al final te daré 1 ticket por cada 10 puntos. Los billetes se pueden canjear por productos de nuestras tiendas. Entonces... ¿te gustaría probarlo? La tarifa es de sólo 200 coins.",
        ["No thanks."] = "No, gracias.",
        ["**Competition Judge** Hello again. How can I help you?"] = "**Competition Judge** Hola de nuevo. ¿Le puedo ayudar en algo?",
        ["Well, I actually don't have any more arrows."] = "Bueno, en realidad no tengo más flechas.",
        ["I can sell you 10 more arrows for 100 coins."] = "Puedo venderte 10 flechas más por 100 coins.",
        ["What would you like"] = "¿Qué te gustaría?",
        ["Sure, I'll take some."] = "Claro, tomaré un poco.",
        ["You buy 10 bronze arrows from the judge."] = "Le compras 10 flechas de bronce al juez.",
        ["You'll need to be wielding a bow to fire arrows at the target. Um... You're meant to fire from behind the hay bales. Well done. Your score is: 460. When you have enough inventory space, I'll give you your reward. Well done. Your score is: 460. You have earned 46 Archery tickets. Hello there. Would you like to take part in the archery competition? It only costs 200 coins to enter."] = "Tendrás que empuñar un arco para disparar flechas al objetivo. Um... Se supone que debes disparar desde detrás de los fardos de heno. Bien hecho. Tu puntuación es: 460. Cuando tengas suficiente espacio en el inventario, te daré tu recompensa. Bien hecho. Tu puntuación es: 460. Has ganado 46 billetes de tiro con arco. Hola. ¿Te gustaría participar en el concurso de tiro con arco? La entrada solo cuesta 200 coins.",
        ["Remind me of the rules, please."] = "Recuérdame las reglas, por favor.",
        ["**Competition Judge**The rules are very simple: You're given 10 shots at the targets. For each hit you will receive points. At the end I'll give you 1 ticket for every 10 points. The tickets can be exchanged for goods from our stores."] = "**Competition Judge**Las reglas son muy simples: tienes 10 disparos a los objetivos. Por cada acierto recibirás puntos. Al final te daré 1 ticket por cada 10 puntos. Los billetes se pueden canjear por productos de nuestras tiendas.",
        ["How am I doing so far?"] = "¿Cómo me va hasta ahora?",
        ["You haven't started yet. Stand behind the hay bales and shoot those bronze arrows at the targets."] = "Aún no has empezado. Párate detrás de los fardos de heno y dispara esas flechas de bronce a los objetivos.",
        ["I'm fine, thanks."] = "Estoy bien, gracias.",
    },
    ["Concerned mother"] = {
        ["Hello. What can I do for you?"] = "Hola. ¿Qué puedo hacer por ti?",
        ["What are you and your daughter talking about?"] = "¿De qué están hablando usted y su hija?",
        ["I've found a good way to keep her in line! When she's bad, I threaten to send her to Lumbridge!"] = "¡He encontrado una buena manera de mantenerla a raya! ¡Cuando se porta mal, la amenazo con enviarla a Lumbridge!",
        ["What's happening in Lumbridge?"] = "¿Qué está pasando en Lumbridge?",
        ["You don't know? They say a portal to another dimension opened and not only did Saradomin himself return, but so did Zamorak!"] = "¿No lo sabes? Dicen que se abrió un portal a otra dimensión y no solo regresó el propio Saradomin, ¡sino también Zamorak!",
        ["They've been locked in mortal combat ever since. I'm terrified that they might come over here."] = "Han estado enfrascados en un combate mortal desde entonces. Tengo miedo de que vengan aquí.",
        ["People have been flocking to join their armies and fight in the battle. If you have any sense, though, you'll stay away from it."] = "La gente ha acudido en masa para unirse a sus ejércitos y luchar en la batalla. Pero si tienes algo de sentido común, te mantendrás alejado de ello.",
        ["I'm just relieved that we're so far away from it here. I hope nothing happens to us!"] = "Me siento aliviada de que estemos tan lejos de esto. Espero que no nos pase nada!",
        ["Where is the battlefield?"] = "¿Dónde está el campo de batalla?",
        ["It's supposed to be near the castle in Lumbridge. There's camps supporting both Zamorak and Saradomin around a battlefield there."] = "Se supone que está cerca del castillo en Lumbridge. Hay campamentos que apoyan tanto a Zamorak como a Saradomin alrededor de un campo de batalla allí.",
        ["It's sad to hear of so many going in to join the fight. I want a peaceful world where I can raise my daughter."] = "Es triste saber que tantas personas se unen a la lucha. Quiero un mundo pacífico donde pueda criar a mi hija.",
        ["Why are people joining?"] = "¿Por qué se une la gente?",
        ["I've heard that both Zamorak and Saradomin want people to help them collect power - something called 'divine tears'."] = "He oído que tanto Zamorak como Saradomin quieren que la gente los ayude a recolectar poder, algo llamado \"lágrimas divinas\".",
        ["They're concentrated on the battlefield, but you can find them anywhere if you're lucky."] = "Están concentrados en el campo de batalla, pero puedes encontrarlos en cualquier lugar si tienes suerte.",
        ["It's not just warriors they are looking for, but also skilled individuals to aid in their war effort."] = "No solo buscan guerreros, sino también personas capacitadas para ayudar en su esfuerzo bélico.",
        ["Both camps are offering rewards for the help they are given."] = "Ambos campamentos ofrecen recompensas por la ayuda que reciben.",
        ["I hope you stay far away though. No good can come from fooling around with the gods."] = "Aunque espero que te quedes lejos. Nada bueno puede resultar de jugar con los dioses.",
        ["Thanks for the info!"] = "¡Gracias por la información!",
        ["I must get on with my shopping."] = "Debo seguir con mis compras.",
        ["Isn't that cruel?"] = "¿No es eso cruel?",
        ["I wouldn't really do it! Not with all the fighting around Lumbridge at the moment!"] = "¡Realmente no lo haría! ¡No con todas las peleas alrededor de Lumbridge en este momento!",
        ["What sort of mother do you take me for?"] = "¿Por qué clase de madre me tomas?",
        ["I'd keep away from there too if you know what's good for you. Messing with the gods' business is dangerous."] = "Yo también me mantendría alejado de allí si sabes lo que es bueno para ti. Meterse en los asuntos de los dioses es peligroso.",
        ["Oh, I see."] = "Ah, ya veo.",
        ["Yes, my girl, we're far away from Lumbridge here!"] = "Sí, niña, ¡aquí estamos muy lejos de Lumbridge!",
        ["You should behave or Zamorak will eat you!"] = "¡Debes comportarte o Zamorak te comerá!",
        ["Not if you behave yourself"] = "No si te portas bien",
        ["Just be quiet or I'll send you to Lumbridge!"] = "¡Solo cállate o te enviaré a Lumbridge!",
    },
    ["Cook (Blue Moon Inn)"] = {
        ["What do you want? I'm busy!"] = "¿Qué quieres? ¡Estoy ocupado!",
        ["Can you sell me any food?"] = "¿Puedes venderme algo de comida?",
        ["I suppose I could sell you some cabbage, if you're willing to pay for it. Cabbage is good for you."] = "Supongo que podría venderte un poco de repollo, si estás dispuesto a pagarlo. El repollo es bueno para ti.",
        ["Alright, I'll buy a cabbage."] = "Muy bien, compraré un repollo.",
        ["Thanks, Cook."] = "Gracias, cocinero.",
        ["It's a deal. Now, make sure you eat it all up. Cabbage is good for you."] = "Es un trato. Ahora, asegúrate de comértelo todo. El repollo es bueno para ti.",
        ["You can not afford that."] = "No puedes permitirte eso.",
        ["I said 1 coins! You haven't got 1 coins!"] = "¡Dije 1 coins! ¡No tienes 1 coins!",
        ["Sorry, I'll come back another day."] = "Lo siento, volveré otro día.",
        ["No thanks, I don't like cabbage."] = "No, gracias, no me gusta el repollo.",
        ["Bah! People these days only appreciate junk food."] = "¡Bah! La gente hoy en día sólo aprecia la comida chatarra.",
        ["Can you give me any free food?"] = "¿Puedes darme comida gratis?",
        ["Can you give me any free money?"] = "¿Puedes darme dinero gratis?",
        ["Why should I give you free money?"] = "¿Por qué debería darte dinero gratis?",
        ["Why should I give you free food?"] = "¿Por qué debería darte comida gratis?",
        ["Oh, forget it."] = "Oh, olvídalo.",
        ["I don't want anything from this horrible kitchen."] = "No quiero nada de esta horrible cocina.",
        ["How dare you? I put a lot of effort into cleaning this kitchen. My daily sweat and elbow-grease keep this kitchen clean!"] = "¿Cómo te atreves? Puse mucho esfuerzo en limpiar esta cocina. ¡Mi sudor diario y mi esfuerzo mantienen limpia esta cocina!",
        ["Ewww!"] = "¡Ewww!",
        ["Oh, just leave me alone."] = "Oh, déjame en paz.",
    },
    ["Cook"] = {
        ["What do you want? I'm busy!"] = "¿Qué quieres? ¡Estoy ocupado!",
        ["Can you sell me any food?"] = "¿Puedes venderme algo de comida?",
        ["I suppose I could sell you some cabbage, if you're willing to pay for it. Cabbage is good for you."] = "Supongo que podría venderte un poco de repollo, si estás dispuesto a pagarlo. El repollo es bueno para ti.",
        ["Alright, I'll buy a cabbage."] = "Muy bien, compraré un repollo.",
        ["Thanks, Cook."] = "Gracias, cocinero.",
        ["It's a deal. Now, make sure you eat it all up. Cabbage is good for you."] = "Es un trato. Ahora, asegúrate de comértelo todo. El repollo es bueno para ti.",
        ["You can not afford that."] = "No puedes permitirte eso.",
        ["I said 1 coins! You haven't got 1 coins!"] = "¡Dije 1 coins! ¡No tienes 1 coins!",
        ["Sorry, I'll come back another day."] = "Lo siento, volveré otro día.",
        ["No thanks, I don't like cabbage."] = "No, gracias, no me gusta el repollo.",
        ["Bah! People these days only appreciate junk food."] = "¡Bah! La gente hoy en día sólo aprecia la comida chatarra.",
        ["Can you give me any free food?"] = "¿Puedes darme comida gratis?",
        ["Can you give me any free money?"] = "¿Puedes darme dinero gratis?",
        ["Why should I give you free money?"] = "¿Por qué debería darte dinero gratis?",
        ["Why should I give you free food?"] = "¿Por qué debería darte comida gratis?",
        ["Oh, forget it."] = "Oh, olvídalo.",
        ["I don't want anything from this horrible kitchen."] = "No quiero nada de esta horrible cocina.",
        ["How dare you? I put a lot of effort into cleaning this kitchen. My daily sweat and elbow-grease keep this kitchen clean!"] = "¿Cómo te atreves? Puse mucho esfuerzo en limpiar esta cocina. ¡Mi sudor diario y mi esfuerzo mantienen limpia esta cocina!",
        ["Ewww!"] = "¡Ewww!",
        ["Oh, just leave me alone."] = "Oh, déjame en paz.",
        ["[Menu]: What would you like to say?"] = "[Menú]: ¿Qué te gustaría decir?",
        ["Can you cook me something?"] = "¿Puedes cocinarme algo?",
        ["What? No! Go away."] = "¿Qué? ¡No! Irse.",
        ["Well, you're meant to be a cook. Why can't you cook something for me?"] = "Bueno, estás destinado a ser cocinero. ¿Por qué no puedes cocinarme algo?",
        ["I don't want to, that's why! Now, leave me alone."] = "¡No quiero, por eso! Ahora déjame en paz.",
        ["You're not a very nice man."] = "No eres un hombre muy agradable.",
        ["Yet you keep talking to me!"] = "¡Aun así sigues hablándome!",
        ["Good point. I should stop that."] = "Buen punto. Debería detener eso.",
        ["Yes, do us both a favour."] = "Sí, haznos un favor a ambos.",
        ["Why do you work here?"] = "¿Por qué trabajas aquí?",
        ["Why do you think I work in a disreputable inn filled with rough scoundrels on the very edge of the Wilderness? I work here because I need the job!"] = "¿Por qué crees que trabajo en una posada de mala reputación llena de sinvergüenzas en las afueras de Wilderness? ¡Trabajo aquí porque necesito el trabajo!",
        ["Do you like it?"] = "¿Te gusta?",
        ["Like it? It's sucked the warmth and humanity out of me, and I've become a hollow shell holding nothing but anger, misery and gourmet recipes."] = "¿Te gusta? Me ha quitado la calidez y la humanidad, y me he convertido en un caparazón vacío que no contiene nada más que ira, miseria y recetas gourmet.",
        ["What did you expect to hear? I suppose you expected me to tell you an inspiring story about how working here can teach you to find hope in the darkest places, or how to see the best in everything?"] = "¿Qué esperabas escuchar? Supongo que esperabas que te contara una historia inspiradora sobre cómo trabajar aquí puede enseñarte a encontrar esperanza en los lugares más oscuros o cómo ver lo mejor en todo.",
        ["Well, get those fancy ideas out of your head. Out here you've got nothing but your armour and muscle to protect you from the endless dark and the screaming hordes coming to kill you!"] = "Bueno, quítate esas ideas extravagantes de la cabeza. ¡Aquí afuera no tienes nada más que tu armadura y tus músculos para protegerte de la oscuridad interminable y de las hordas que gritan y vienen a matarte!",
        ["Maybe you should think about moving to a different inn."] = "Quizás deberías pensar en mudarte a una posada diferente.",
        ["Bah! I'm not letting it defeat me. Now, let me concentrate on my cooking."] = "¡Bah! No dejaré que esto me derrote. Ahora, déjame concentrarme en cocinar.",
        ["Okay."] = "Está bien.",
        ["Can you tell me any good jokes?"] = "¿Puedes contarme algún chiste bueno?",
        ["Ohhh, if you insist..."] = "Ohhh, si insistes...",
        ["What did the half-wit say to the cook?"] = "¿Qué le dijo el imbécil al cocinero?",
        ["I don't know."] = "No lo sé.",
        ["[He/She] said 'Can you tell me any good jokes?' Got ya! Hahahaha!"] = "[He/She] dijo: '¿Puedes contarme algún buen chiste?' ¡Te tengo! ¡Jajajaja!",
        ["Whatever."] = "Lo que sea.",
        ["Hello..."] = "Hola...",
        ["I distinctly remember you saying you were going to stop talking to me. Yet here you are again, yakking on and on in my earhole when I'm trying to cook! What do you want now?"] = "Recuerdo claramente que dijiste que ibas a dejar de hablarme. ¡Sin embargo, aquí estás otra vez, parloteando una y otra vez en mi oído cuando intento cocinar! ¿Qué quieres ahora?",
        ["**Cook:** Hello, friend, how is the adventuring going?"] = "**Cocinero:** Hola amigo, ¿cómo va la aventura?",
        ["Select an Option"] = "Selecciona una opción",
        ["I'm getting strong and mighty."] = "Me estoy volviendo fuerte y poderoso.",
        ["I'm getting strong and mighty. Grr."] = "Me estoy volviendo fuerte y poderoso. gr.",
        ["Glad to hear it."] = "Me alegra oírlo.",
        ["I keep on dying."] = "Sigo muriendo.",
        ["Ah, well, at least you keep coming back to life too!"] = "Ah, bueno, ¡al menos tú también sigues volviendo a la vida!",
        ["Can I use your range?"] = "¿Puedo usar tu rango?",
        ["Go ahead! It's a very good range; it's better than most other ranges."] = "¡Adelante! Es una gama muy buena; es mejor que la mayoría de las otras gamas.",
        ["It's called the Cook-o-Matic 25 and it uses a combination of state-of-the-art temperature regulation and magic."] = "Se llama Cook-o-Matic 25 y utiliza una combinación de magia y regulación de temperatura de última generación.",
        ["Will it mean my food will burn less often?"] = "¿Significará que mi comida se quemará con menos frecuencia?",
        ["As long as the food is fairly easy to cook in the first place!"] = "¡Siempre y cuando la comida sea bastante fácil de cocinar en primer lugar!",
        ["Here, take this manual. It should tell you everything you need to know about this range."] = "Toma, toma este manual. Debería decirle todo lo que necesita saber sobre este rango.",
        ["[The cook hands you a manual.]"] = "[El cocinero te entrega un manual.]",
        ["The manual you have in your inventory should tell you more."] = "El manual que tienes en tu inventario debería decirte más.",
        ["Thanks!"] = "¡Gracias!",
        ["Ah, hello again, my friend! You know, the Duke really enjoyed the cake and I wanted to thank you a bit more."] = "¡Ah, hola de nuevo, amigo! Sabes, el Duque disfrutó mucho el pastel y quería agradecerte un poco más.",
        ["Great, but I need to free up some space in my inventory first. I'll be right back."] = "Genial, pero primero necesito liberar algo de espacio en mi inventario. Ya vuelvo.",
        ["The cook hands you 500 coins and 20 sardines."] = "El cocinero te entrega 500 coins y 20 sardinas.",
        ["Congratulations! You have completed: 'Cook's Delights' - Claim the Cook's extra rewards after 'Cook's Assistant'."] = "¡Felicitaciones! Has completado: 'Delicias del cocinero': reclama las recompensas adicionales del cocinero después de 'Cook's Assistant'.",
        ["Thank you!"] = "¡Gracias!",
        ["**Cook:** Seriously, you were great! I can't believe I nearly caused all of those people to be killed!"] = "**Cocinero:** En serio, ¡estuviste genial! ¡No puedo creer que casi causé que mataran a todas esas personas!",
        ["You really got my bacon out of the fire there!"] = "¡Realmente sacaste mi tocino del fuego!",
        ["Do you have any other quests for me?"] = "¿Tienes otras misiones para mí?",
        ["That last one of yours was fun!"] = "¡Ese último tuyo fue divertido!",
        ["Ooh dear, yes I do!"] = "Oh querido, ¡sí, lo quiero!",
        ["It's the Duke of Lumbridge's birthday today, and I need to bake him a cake!"] = "¡Hoy es el cumpleaños del Duque de Lumbridge y necesito prepararle un pastel!",
        ["I need you to bring me some eggs, some flour, some milk and a chocolate bar..."] = "Necesito que me traigas unos huevos, un poco de harina, un poco de leche y una barra de chocolate...",
        ["Nah, not really, I'm just messing with you! Thanks for all your help, I know I can count on you again in the future!"] = "No, realmente no, ¡solo estoy jugando contigo! Gracias por toda tu ayuda, ¡sé que puedo contar contigo nuevamente en el futuro!",
        ["I am getting strong and mighty."] = "Me estoy volviendo fuerte y poderoso.",
        ["Can you tell me anything about that chest in the basement?"] = "¿Puedes decirme algo sobre ese cofre en el sótano?",
        ["So that chest in the basement that suddenly appeared along with the Culinaromancer..."] = "Entonces ese cofre en el sótano que apareció de repente junto con el Culinaromancer...",
        ["Can you tell me anything about it?"] = "¿Puedes contarme algo al respecto?",
        ["You mean you didn't check it out yet?"] = "¿Quieres decir que aún no lo has comprobado?",
        ["I really think you should, it seems to be some kind of magical cooking chest, I found a bunch of food in it earlier, along with a bunch of weird looking kitchen equipment and some snazzy gloves!"] = "Realmente creo que deberías, parece ser una especie de cofre de cocina mágico. Encontré un montón de comida antes, junto con un montón de equipos de cocina de aspecto extraño y unos guantes elegantes.",
        ["I know you've been very active around Lumbridge and Draynor. Perhaps I could reward you with some food?"] = "Sé que has estado muy activo con Lumbridge y Draynor. ¿Quizás podría recompensarte con algo de comida?",
        ["Yes, please."] = "Sí, por favor.",
        ["There you go."] = "Ahí lo tienes.",
        ["No, thanks."] = "No, gracias.",
        ["What happened to the castle?"] = "¿Qué pasó con el castillo?",
        ["The castle really did suffer in the battle of Lumbridge. I'm glad it's over!"] = "El castillo realmente sufrió en la batalla de Lumbridge. ¡Me alegro que haya terminado!",
        ["People came from all over the world to help rebuild, and now things are getting back to normal. I'm glad - I have important things to cook and I'm not letting anything get in the way!"] = "Vino gente de todo el mundo para ayudar en la reconstrucción y ahora las cosas están volviendo a la normalidad. Me alegro, tengo cosas importantes que cocinar y no dejaré que nada se interponga en mi camino.",
        ["Ive always wondered how many cannons the castle has. Could you find out for me?"] = "Siempre me he preguntado cuántos cañones tiene el castillo. ¿Podrías averiguarlo por mí?",
        ["[The cook has given you a challenge scroll!]"] = "[¡El cocinero te ha dado un pergamino de desafío!]",
        ["Please enter the answer to the question."] = "Ingrese la respuesta a la pregunta.",
        ["Enter amount: [Input field]"] = "Ingrese la cantidad: [Input field]",
        ["Hmm, I don't think that's right."] = "Hmm, no creo que sea correcto.",
        ["[The cook has given you another clue scroll!]"] = "[¡El cocinero te ha dado otro pergamino de pistas!]",
        ["[You've found a casket!]"] = "[¡Has encontrado un ataúd!]",
        ["Cheers!"] = "¡Salud!",
        ["You don't have space in your backpack right now."] = "No tienes espacio en tu backpack en este momento.",
        ["Hello! I'm here on behalf of Leslie, they said you should be expecting me."] = "¡Hola! Estoy aquí en nombre de Leslie, dijeron que deberías estar esperándome.",
        ["Ahh, yes! I take it you have the Woad Leaves I need?"] = "¡Ahh, sí! ¿Supongo que tienes las hojas de glasto que necesito?",
        ["Yeah!"] = "¡Sí!",
        ["I've also got this lovely flax."] = "También tengo este precioso lino.",
        ["I've also got this perfectly dry wheat."] = "También tengo este trigo perfectamente seco.",
        ["I've also got some marigolds."] = "También tengo algunas caléndulas.",
        ["I've also got this ice cold beer."] = "También tengo esta cerveza helada.",
        ["Okay... That's nice!"] = "Está bien... ¡Eso es bueno!",
        ["Where shall I put all of this? On the side over here?"] = "¿Dónde debo poner todo esto? ¿En el lado de aquí?",
        ["All? I only need the woad leaves."] = "¿Todos? Sólo necesito las hojas de glasto.",
        ["Leslie gave me a list and there was far more than just woad leaves on it..."] = "Leslie me dio una lista y había mucho más que hojas de glasto en ella...",
        ["Sorry, based on the recipe they gave me, I only needed woad leaves."] = "Lo siento, según la receta que me dieron, solo necesitaba hojas de glasto.",
        ["Of course."] = "Por supuesto.",
        ["Where shall I put them? On the side over here?"] = "¿Dónde los pongo? ¿En el lado de aquí?",
        ["Yeah, if you could pass them over, that would be perfect."] = "Sí, si pudieras pasarlos por alto, sería perfecto.",
        ["Here we go."] = "Allá vamos.",
        ["Thanks! This will take a while to make."] = "¡Gracias! Tomará un tiempo hacer esto.",
        ["I can wait."] = "Puedo esperar.",
        ["Did I fall asleep?"] = "¿Me quedé dormido?",
        ["Right there on my floor, yes."] = "Allí mismo, en mi piso, sí.",
        ["Sorry about that."] = "Lo siento.",
        ["If you make some backpack space, I can give you the mush."] = "Si haces un poco de espacio para backpack, puedo darte la papilla.",
        ["Here's the rich mush for Leslie."] = "Aquí tenéis la rica papilla para Leslie.",
        ["Hey, who said you could use that?"] = "Oye, ¿quién dijo que podrías usar eso?",
        ["You're not artistocracy, but I suppose you'd do. Do you want a good cook for [number] coins?"] = "No eres artistacracia, pero supongo que lo harías. ¿Quieres un buen cocinero para [número] coins?",
        ["What can you do?"] = "¿Qué puedes hacer?",
        ["I, sir, am the finest cook in all Gielinor! I can also make good time going to the bank or the sawmill."] = "¡Yo, señor, soy el mejor cocinero de todo Gielinor! También puedo pasar un buen rato yendo al banco o al aserradero.",
        ["Tell me about your previous jobs"] = "Cuéntame sobre tus trabajos anteriores.",
        ["Tell me about your previous jobs."] = "Cuéntame sobre tus trabajos anteriores.",
        ["I used to be the cook for the old Duke of Lumbridge. Visiting dignitaries praised me for my fine banquets!"] = "Solía ser el cocinero del antiguo Duque de Lumbridge. ¡Los dignatarios visitantes me elogiaron por mis excelentes banquetes!",
        ["But then someone found a rule that said that only one family could hold that post."] = "Pero entonces alguien encontró una regla que decía que solo una familia podía ocupar ese puesto.",
        ["Overnight I was fired and replaced by some fool who can't even bake a cake without help!"] = "¡De la noche a la mañana me despidieron y me reemplazaron por un tonto que ni siquiera puede hornear un pastel sin ayuda!",
        ["You're hired!"] = "¡Estás contratado!",
        ["I'm not getting involved in these new houses. Hopefully soon."] = "No me involucraré en estas nuevas casas. Ojalá sea pronto.",
        ["You already have a servant."] = "Ya tienes un sirviente.",
    },
    ["Cook (Jolly Boar Inn)"] = {
        ["What do you want? I'm busy!"] = "¿Qué quieres? ¡Estoy ocupado!",
        ["[Menu]: What would you like to say?"] = "[Menú]: ¿Qué te gustaría decir?",
        ["Can you cook me something?"] = "¿Puedes cocinarme algo?",
        ["What? No! Go away."] = "¿Qué? ¡No! Irse.",
        ["Well, you're meant to be a cook. Why can't you cook something for me?"] = "Bueno, estás destinado a ser cocinero. ¿Por qué no puedes cocinarme algo?",
        ["I don't want to, that's why! Now, leave me alone."] = "¡No quiero, por eso! Ahora déjame en paz.",
        ["You're not a very nice man."] = "No eres un hombre muy agradable.",
        ["Yet you keep talking to me!"] = "¡Aun así sigues hablándome!",
        ["Good point. I should stop that."] = "Buen punto. Debería detener eso.",
        ["Yes, do us both a favour."] = "Sí, haznos un favor a ambos.",
        ["Why do you work here?"] = "¿Por qué trabajas aquí?",
        ["Why do you think I work in a disreputable inn filled with rough scoundrels on the very edge of the Wilderness? I work here because I need the job!"] = "¿Por qué crees que trabajo en una posada de mala reputación llena de sinvergüenzas en las afueras de Wilderness? ¡Trabajo aquí porque necesito el trabajo!",
        ["Do you like it?"] = "¿Te gusta?",
        ["Like it? It's sucked the warmth and humanity out of me, and I've become a hollow shell holding nothing but anger, misery and gourmet recipes."] = "¿Te gusta? Me ha quitado la calidez y la humanidad, y me he convertido en un caparazón vacío que no contiene nada más que ira, miseria y recetas gourmet.",
        ["What did you expect to hear? I suppose you expected me to tell you an inspiring story about how working here can teach you to find hope in the darkest places, or how to see the best in everything?"] = "¿Qué esperabas escuchar? Supongo que esperabas que te contara una historia inspiradora sobre cómo trabajar aquí puede enseñarte a encontrar esperanza en los lugares más oscuros o cómo ver lo mejor en todo.",
        ["Well, get those fancy ideas out of your head. Out here you've got nothing but your armour and muscle to protect you from the endless dark and the screaming hordes coming to kill you!"] = "Bueno, quítate esas ideas extravagantes de la cabeza. ¡Aquí afuera no tienes nada más que tu armadura y tus músculos para protegerte de la oscuridad interminable y de las hordas que gritan y vienen a matarte!",
        ["Maybe you should think about moving to a different inn."] = "Quizás deberías pensar en mudarte a una posada diferente.",
        ["Bah! I'm not letting it defeat me. Now, let me concentrate on my cooking."] = "¡Bah! No dejaré que esto me derrote. Ahora, déjame concentrarme en cocinar.",
        ["Okay."] = "Está bien.",
        ["Can you tell me any good jokes?"] = "¿Puedes contarme algún chiste bueno?",
        ["Ohhh, if you insist..."] = "Ohhh, si insistes...",
        ["What did the half-wit say to the cook?"] = "¿Qué le dijo el imbécil al cocinero?",
        ["I don't know."] = "No lo sé.",
        ["[He/She] said 'Can you tell me any good jokes?' Got ya! Hahahaha!"] = "[He/She] dijo: '¿Puedes contarme algún buen chiste?' ¡Te tengo! ¡Jajajaja!",
        ["Whatever."] = "Lo que sea.",
        ["Hello..."] = "Hola...",
        ["I distinctly remember you saying you were going to stop talking to me. Yet here you are again, yakking on and on in my earhole when I'm trying to cook! What do you want now?"] = "Recuerdo claramente que dijiste que ibas a dejar de hablarme. ¡Sin embargo, aquí estás otra vez, parloteando una y otra vez en mi oído cuando intento cocinar! ¿Qué quieres ahora?",
    },
    ["Cook (Lumbridge)"] = {
        ["**Cook:** Hello, friend, how is the adventuring going?"] = "**Cocinero:** Hola amigo, ¿cómo va la aventura?",
        ["Select an Option"] = "Selecciona una opción",
        ["I'm getting strong and mighty."] = "Me estoy volviendo fuerte y poderoso.",
        ["I'm getting strong and mighty. Grr."] = "Me estoy volviendo fuerte y poderoso. gr.",
        ["Glad to hear it."] = "Me alegra oírlo.",
        ["I keep on dying."] = "Sigo muriendo.",
        ["Ah, well, at least you keep coming back to life too!"] = "Ah, bueno, ¡al menos tú también sigues volviendo a la vida!",
        ["Can I use your range?"] = "¿Puedo usar tu rango?",
        ["Go ahead! It's a very good range; it's better than most other ranges."] = "¡Adelante! Es una gama muy buena; es mejor que la mayoría de las otras gamas.",
        ["It's called the Cook-o-Matic 25 and it uses a combination of state-of-the-art temperature regulation and magic."] = "Se llama Cook-o-Matic 25 y utiliza una combinación de magia y regulación de temperatura de última generación.",
        ["Will it mean my food will burn less often?"] = "¿Significará que mi comida se quemará con menos frecuencia?",
        ["As long as the food is fairly easy to cook in the first place!"] = "¡Siempre y cuando la comida sea bastante fácil de cocinar en primer lugar!",
        ["Here, take this manual. It should tell you everything you need to know about this range."] = "Toma, toma este manual. Debería decirle todo lo que necesita saber sobre este rango.",
        ["[The cook hands you a manual.]"] = "[El cocinero te entrega un manual.]",
        ["The manual you have in your inventory should tell you more."] = "El manual que tienes en tu inventario debería decirte más.",
        ["Thanks!"] = "¡Gracias!",
        ["Ah, hello again, my friend! You know, the Duke really enjoyed the cake and I wanted to thank you a bit more."] = "¡Ah, hola de nuevo, amigo! Sabes, el Duque disfrutó mucho el pastel y quería agradecerte un poco más.",
        ["Great, but I need to free up some space in my inventory first. I'll be right back."] = "Genial, pero primero necesito liberar algo de espacio en mi inventario. Ya vuelvo.",
        ["The cook hands you 500 coins and 20 sardines."] = "El cocinero te entrega 500 coins y 20 sardinas.",
        ["Congratulations! You have completed: 'Cook's Delights' - Claim the Cook's extra rewards after 'Cook's Assistant'."] = "¡Felicitaciones! Has completado: 'Delicias del cocinero': reclama las recompensas adicionales del cocinero después de 'Cook's Assistant'.",
        ["Thank you!"] = "¡Gracias!",
        ["**Cook:** Seriously, you were great! I can't believe I nearly caused all of those people to be killed!"] = "**Cocinero:** En serio, ¡estuviste genial! ¡No puedo creer que casi causé que mataran a todas esas personas!",
        ["You really got my bacon out of the fire there!"] = "¡Realmente sacaste mi tocino del fuego!",
        ["Do you have any other quests for me?"] = "¿Tienes otras misiones para mí?",
        ["That last one of yours was fun!"] = "¡Ese último tuyo fue divertido!",
        ["Ooh dear, yes I do!"] = "Oh querido, ¡sí, lo quiero!",
        ["It's the Duke of Lumbridge's birthday today, and I need to bake him a cake!"] = "¡Hoy es el cumpleaños del Duque de Lumbridge y necesito prepararle un pastel!",
        ["I need you to bring me some eggs, some flour, some milk and a chocolate bar..."] = "Necesito que me traigas unos huevos, un poco de harina, un poco de leche y una barra de chocolate...",
        ["Nah, not really, I'm just messing with you! Thanks for all your help, I know I can count on you again in the future!"] = "No, realmente no, ¡solo estoy jugando contigo! Gracias por toda tu ayuda, ¡sé que puedo contar contigo nuevamente en el futuro!",
        ["I am getting strong and mighty."] = "Me estoy volviendo fuerte y poderoso.",
        ["Can you tell me anything about that chest in the basement?"] = "¿Puedes decirme algo sobre ese cofre en el sótano?",
        ["So that chest in the basement that suddenly appeared along with the Culinaromancer..."] = "Entonces ese cofre en el sótano que apareció de repente junto con el Culinaromancer...",
        ["Can you tell me anything about it?"] = "¿Puedes contarme algo al respecto?",
        ["You mean you didn't check it out yet?"] = "¿Quieres decir que aún no lo has comprobado?",
        ["I really think you should, it seems to be some kind of magical cooking chest, I found a bunch of food in it earlier, along with a bunch of weird looking kitchen equipment and some snazzy gloves!"] = "Realmente creo que deberías, parece ser una especie de cofre de cocina mágico. Encontré un montón de comida antes, junto con un montón de equipos de cocina de aspecto extraño y unos guantes elegantes.",
        ["I know you've been very active around Lumbridge and Draynor. Perhaps I could reward you with some food?"] = "Sé que has estado muy activo con Lumbridge y Draynor. ¿Quizás podría recompensarte con algo de comida?",
        ["Yes, please."] = "Sí, por favor.",
        ["There you go."] = "Ahí lo tienes.",
        ["No, thanks."] = "No, gracias.",
        ["What happened to the castle?"] = "¿Qué pasó con el castillo?",
        ["The castle really did suffer in the battle of Lumbridge. I'm glad it's over!"] = "El castillo realmente sufrió en la batalla de Lumbridge. ¡Me alegro que haya terminado!",
        ["People came from all over the world to help rebuild, and now things are getting back to normal. I'm glad - I have important things to cook and I'm not letting anything get in the way!"] = "Vino gente de todo el mundo para ayudar en la reconstrucción y ahora las cosas están volviendo a la normalidad. Me alegro, tengo cosas importantes que cocinar y no dejaré que nada se interponga en mi camino.",
        ["Ive always wondered how many cannons the castle has. Could you find out for me?"] = "Siempre me he preguntado cuántos cañones tiene el castillo. ¿Podrías averiguarlo por mí?",
        ["[The cook has given you a challenge scroll!]"] = "[¡El cocinero te ha dado un pergamino de desafío!]",
        ["Please enter the answer to the question."] = "Ingrese la respuesta a la pregunta.",
        ["Enter amount: [Input field]"] = "Ingrese la cantidad: [Input field]",
        ["Hmm, I don't think that's right."] = "Hmm, no creo que sea correcto.",
        ["[The cook has given you another clue scroll!]"] = "[¡El cocinero te ha dado otro pergamino de pistas!]",
        ["[You've found a casket!]"] = "[¡Has encontrado un ataúd!]",
        ["Cheers!"] = "¡Salud!",
        ["You don't have space in your backpack right now."] = "No tienes espacio en tu backpack en este momento.",
        ["Hello! I'm here on behalf of Leslie, they said you should be expecting me."] = "¡Hola! Estoy aquí en nombre de Leslie, dijeron que deberías estar esperándome.",
        ["Ahh, yes! I take it you have the Woad Leaves I need?"] = "¡Ahh, sí! ¿Supongo que tienes las hojas de glasto que necesito?",
