    ["Creekjoints"] = {
        ["What you think of totems, humie? I design!"] = "¿Qué piensas de los tótems, humie? ¡Yo diseño!",
        ["They're very evocative."] = "Son muy evocadores.",
        ["Mama Rummertum my best work."] = "Mama Rummertum mi mejor trabajo.",
